from produire import produire,paras,table,steps
parts=[
('La sialolithiase sous-mandibulaire correspond à un calcul dans la glande ou son canal excréteur. Les {conséquences obstructives} expliquent la douleur et le gonflement aux repas.',paras('Elle doit être distinguée d’une simple sensation de bouche sèche. Une obstruction peut se compliquer d’inflammation ou d’infection, mais un calcul n’est pas synonyme d’infection bactérienne.')),
('La localisation sous-mandibulaire est une localisation fréquente des calculs salivaires. Les {contextes de survenue} orientent sans fournir un classement universel des masses cervicales.',paras('Les épisodes peuvent récidiver lors de la stimulation salivaire, parfois depuis longtemps avant le diagnostic. Une masse persistante indépendante des repas nécessite un autre raisonnement, même chez une personne ayant déjà eu un calcul.')),
('Le canal sous-mandibulaire débouche dans le plancher buccal. Les {mécanismes de stase} expliquent le caractère intermittent des symptômes.',paras('Lors d’un repas, la sécrétion augmente en amont de l’obstacle, provoquant tension et douleur. La stase peut favoriser une sialadénite ; une tuméfaction du plancher peut ensuite menacer les voies aériennes si l’infection s’étend.')),
('Rechercher fièvre, infection étendue et menace respiratoire. Les {signes d’alarme} imposent une orientation urgente.',paras('Gonflement rapide du plancher ou de la langue, dyspnée, salive non avalée, trismus, sepsis ou tuméfaction cervicale importante nécessitent une prise en charge hospitalière. Une douleur avec pus à l’orifice suggère une infection associée et demande un traitement adapté.')),
('L’entretien recherche le lien avec les repas et les récidives. Les {questions discriminantes} précisent cause obstructive et complication.',paras('Demander siège, durée du gonflement, résolution spontanée, fièvre, goût purulent et traitements antérieurs. Préciser déshydratation, sécheresse, médicaments et interventions salivaires ; une masse continue ne doit pas être assimilée à une colique salivaire.')),
('Examiner la région sous-mandibulaire et l’orifice du canal. Les {gestes ciblés} recherchent calcul et qualité de la salive.',paras('Une palpation bimanuelle douce du plancher peut percevoir un calcul distal ; examiner les deux côtés. Rechercher rougeur, pus, induration et adénopathies. Ne pas instrumenter le canal à l’aveugle ni tenter une extraction domestique.')),
('Le rythme alimentaire est évocateur sans être exclusif. Le {diagnostic différentiel} comprend d’autres causes de gonflement salivaire ou cervical.',table(['Profil','Cause possible'],[['Douleur et gonflement aux repas.','Calcul ou sténose canalaire.'],['Glande douloureuse fébrile, pus.','Sialadénite bactérienne, avec ou sans calcul.'],['Sécheresse oculaire et buccale, gonflements répétés.','Maladie de Sjögren.'],['Masse persistante, ferme ou progressive.','Tumeur glandulaire, ganglion ou autre masse à explorer.'],['Douleur dentaire et plancher gonflé.','Infection odontogène profonde.']])) ,
('Le diagnostic associe tableau obstructif et identification du calcul. Les {arguments positifs} peuvent être cliniques ou obtenus par imagerie.',paras('Un calcul visible ou palpable au canal est fortement évocateur. L’absence de calcul palpable n’exclut pas une localisation plus profonde ; l’imagerie précise obstacle et dilatation en amont.')),
('L’échographie est souvent utile pour rechercher calcul et dilatation. Les {examens de deuxième intention} dépendent de la question clinique.',paras('Un scanner peut préciser un calcul non identifié ou une complication ; son protocole dépend de la recherche d’obstacle ou d’extension infectieuse. La sialendoscopie visualise le canal et peut permettre un traitement ; elle ne remplace pas la prise en charge initiale d’une urgence respiratoire.')),
('L’{arbre de décision} sépare obstruction simple et complication. Le traitement définitif dépend de la localisation et de l’accessibilité du calcul.',steps('Écarter menace respiratoire et infection sévère.', 'Confirmer l’obstruction par examen et imagerie adaptée.', 'Pour une forme simple, proposer mesures conservatrices et avis spécialisé si persistance ou récidive.', 'Discuter extraction endoscopique, fragmentation, abord combiné ou autre chirurgie selon anatomie ; traiter une infection associée.')),
('Les mesures initiales peuvent aider le drainage dans une forme non compliquée. Les {options spécialisées} visent à lever l’obstacle en préservant la glande si possible.',paras('Hydratation adaptée, massage doux et stimulation salivaire non irritante peuvent être proposés selon tolérance. Une douleur croissante, de la fièvre ou une extension imposent de réévaluer plutôt que poursuivre ces seuls gestes.', 'La sialendoscopie permet parfois extraction par panier ou pince ; un calcul plus volumineux peut nécessiter fragmentation ou abord combiné. L’antibiothérapie est réservée à une infection associée et ne dissout pas le calcul ; un abcès peut nécessiter drainage.')),
('La {prévention des récidives} comprend hygiène buccale et correction des facteurs de stase modifiables. Aucun conseil ne garantit l’absence de nouveau calcul.',paras('Maintenir une hydratation adaptée, suivre les conseils après intervention et revoir les médicaments favorisant la sécheresse avec le prescripteur. Faire contrôler une récidive plutôt que répéter des antibiotiques sans vérifier l’obstacle.')),
('Le gonflement rythmé par les repas oriente vers une obstruction salivaire. L’absence de calcul palpable ne l’exclut pas. Antibiotique et extraction ne répondent pas au même problème. Une infection du plancher peut devenir une urgence respiratoire.','')]
quiz=[('Quel rythme évoque une colique salivaire ?','Douleur et gonflement lors des repas.'),('Où débouche le canal sous-mandibulaire ?','Dans le plancher buccal près du frein lingual.'),('Tout calcul implique-t-il une infection ?','Non.'),('L’absence de calcul palpable exclut-elle le diagnostic ?','Non : il peut être profond.'),('Quel examen d’imagerie est souvent utile en première approche ?','L’échographie.'),('Le scanner a-t-il toujours le même protocole ?','Non : il dépend de la question, obstacle ou complication.'),('Que suggère du pus à l’orifice ?','Une infection associée.'),('Une masse continue sans lien aux repas est-elle forcément un calcul ?','Non : envisager tumeur ou autre cause.'),('Peut-on instrumenter le canal à l’aveugle ?','Non.'),('Un antibiotique dissout-il un calcul ?','Non.'),('Que permet parfois la sialendoscopie ?','Visualiser et retirer ou fragmenter un obstacle.'),('Tout calcul impose-t-il l’ablation de la glande ?','Non : des techniques conservatrices existent.'),('Que faire devant gonflement du plancher et dyspnée ?','Prise en charge urgente des voies aériennes et de l’infection.'),('Une récidive justifie-t-elle seulement la répétition d’antibiotiques ?','Non : rechercher et traiter l’obstacle.')]
produire(8,parts,quiz,(9,22))
